class Solution {
public:
    int maxTastiness(std::vector<int>& price, std::vector<int>& tastiness, int maxAmount, int maxCoupons) {
        int n = price.size();
        std::vector<std::vector<int>> dp(maxAmount + 1, std::vector<int>(maxCoupons + 1, 0));

        for (int i = 0; i < n; i++) {
            int p = price[i], t = tastiness[i];
            int half_p = p / 2;
            for (int a = maxAmount; a >= 0; a--) {
                for (int c = maxCoupons; c >= 0; c--) {
                    if (a >= p) dp[a][c] = std::max(dp[a][c], dp[a - p][c] + t);
                    if (c >= 1 && a >= half_p) dp[a][c] = std::max(dp[a][c], dp[a - half_p][c - 1] + t);
                }
            }
        }
        return dp[maxAmount][maxCoupons];
    }
};

class Solution {
    public int maxTastiness(int[] price, int[] tastiness, int maxAmount, int maxCoupons) {
        int n = price.length;
        int[][] dp = new int[maxAmount + 1][maxCoupons + 1];

        for (int i = 0; i < n; i++) {
            int p = price[i], t = tastiness[i];
            int halfP = p / 2;
            for (int a = maxAmount; a >= 0; a--) {
                for (int c = maxCoupons; c >= 0; c--) {
                    if (a >= p) dp[a][c] = Math.max(dp[a][c], dp[a - p][c] + t);
                    if (c >= 1 && a >= halfP) dp[a][c] = Math.max(dp[a][c], dp[a - halfP][c - 1] + t);
                }
            }
        }
        return dp[maxAmount][maxCoupons];
    }
}

var maxTastiness = function(price, tastiness, maxAmount, maxCoupons) {
    const n = price.length;
    const dp = Array.from({ length: maxAmount + 1 }, () => new Array(maxCoupons + 1).fill(0));

    for (let i = 0; i < n; i++) {
        const p = price[i], t = tastiness[i];
        const halfP = Math.floor(p / 2);
        for (let a = maxAmount; a >= 0; a--) {
            for (let c = maxCoupons; c >= 0; c--) {
                if (a >= p) dp[a][c] = Math.max(dp[a][c], dp[a - p][c] + t);
                if (c >= 1 && a >= halfP) dp[a][c] = Math.max(dp[a][c], dp[a - halfP][c - 1] + t);
            }
        }
    }
    return dp[maxAmount][maxCoupons];
};
